    'w.opschrijven': 'записвам',
    'w.latenzien': 'показвам',
    'w.ondertiteling': 'субтитри (говор като текст)',
    'w.instructie': 'инструкция',
    'w.plaatje': 'картинка',
    's.understood.1': 'Ще го запишете ли?',
    's.understood.2': 'Можете ли да го покажете?',
    's.understood.3': 'Има ли инструкция с картинки?',
    'c.understood.q': 'Първо разчисти, после опаковай.',
    'c.understood.a': 'Значи първо трябва да разчистя?',
    'l.keeplearning': 'Продължавай да учиш',
